        "en": "https://www.qrlink.sk/new/en/castles/putnicke-miesto-zivcakova/",
        "de": "https://www.qrlink.sk/new/de/castles/putnicke-miesto-zivcakova/",
        "ru": "https://www.qrlink.sk/new/ru/castles/putnicke-miesto-zivcakova/",
