        "ru": "https://www.qrlink.sk/new/ru/castles/edmund-reitter-odkaz-v-soudobem-paskove/",
        "pl": "https://www.qrlink.sk/new/pl/castles/edmund-reitter-odkaz-v-soudobem-paskove/",
